    [/^(輕鬆|一般|進階|挑戰|困難|雪季)\(估\)$/, m => `${tx(m[1]) || m[1]} (geschätzt)`],
    [/^([\d.]+) km（估）$/, m => `${m[1]} km (geschätzt)`],
    [/^資料來源：林業及自然保育署即時路況$/, () => "Quelle: Live-Wegezustand der Forstbehörde"],
    [/^即時更新於 (.+)$/, m => `aktualisiert ${m[1]}`],
    [/^[^、]{1,10}(?:、[^、]{1,10})+$/, m => {
      const parts = m[0].split("、"); let hit = false;
      const out = parts.map(p => { const r = tx(p.trim()); if (r) hit = true; return r || p; });
      return hit ? out.join(", ") : null;
    }],
    [/^[^　]+(?:　[^　]+)+$/, m => {
      const parts = m[0].split("　"); let hit = false;
      const out = parts.map(p => { const r = tx(p.trim()); if (r) hit = true; return r || p; });
      return hit ? out.join("　") : null;
    }]
